export const meta = {
  name: 'dossier-extract-incremental',
  description: 'Sequentially extract named entities chapter-by-chapter against a running registry',
  phases: [
    { title: 'Extract', detail: 'chapters in reading order, each matched against the known-entity index' },
    { title: 'Describe', detail: 'describe newly-introduced entities in parallel' },
  ],
};

// ===== per-book constants (generated by gen-workflow.ts) =====
const bookNumber = 1;
const sectionDir = '';
const sectionFiles = [];
const startIndex = [];           // compact prior registry: {id, canonicalName, aliases, type}
const startBooksProcessed = [];
const seriesId = '';
const seriesTitle = '';
const seriesAuthor = '';
const seriesNotes = [];          // series-specific prompt rules from <series>/series.json
const agentType = null;          // e.g. 'Explore' (skips CLAUDE.md injection; ~half the per-agent cache write)
const agentModel = null;         // e.g. 'fable'; null inherits the session model
// ===================================================

// Per-agent options from the series profile (omitted keys fall back to harness defaults).
const agentOpts = { ...(agentType ? { agentType } : {}), ...(agentModel ? { model: agentModel } : {}) };

// deterministic helpers mirroring src/registry.ts (the sandbox can't import project files)
function normalizeName(name) {
  return name.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[‘’']/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
}
function makeId(name, existing) {
  const base = normalizeName(name).replace(/\s+/g, '-') || 'entity';
  let id = base;
  let n = 2;
  while (existing.has(id)) id = `${base}-${n++}`;
  return id;
}

// Retry wrapper: agent() returns null on terminal API errors (e.g. Overloaded).
const agentRetry = async (prompt, opts, tries = 4) => {
  for (let attempt = 1; attempt <= tries; attempt++) {
    const label = attempt > 1 ? `${opts.label} (retry ${attempt - 1})` : opts.label;
    const res = await agent(prompt, { ...opts, label });
    if (res) return res;
    if (attempt < tries) log(`${opts.label}: null result, retrying (${attempt}/${tries - 1})`);
  }
  log(`${opts.label}: FAILED after ${tries} attempts`);
  return null;
};

// Matching index. The prior-books part is serialized ONCE and never changes within a book, so
// it forms a stable prompt-cache prefix shared by every chapter agent; this book's discoveries
// are kept separately and appended AFTER it in each prompt. Cache writes are then proportional
// to the handful of new entities, not to the whole index (see dcc/output/token-usage.md).
const frozenIndexJson = JSON.stringify(startIndex);
const addedThisBook = [];
const addedById = new Map();     // id -> entry in addedThisBook (so learned aliases can be attached)
const learnedAliases = new Map(); // id -> Set of name-forms learned via `matched` for FROZEN (prior-book) entities
const ids = new Set(startIndex.map((e) => e.id));
const newById = new Map();   // entities introduced this book (full objects)
const matched = [];          // { id, anchor, aliases } for already-known entities
const snippetsById = new Map();
const hintsById = new Map();

const addSnippet = (id, s) => {
  if (!s) return;
  const arr = snippetsById.get(id) || [];
  if (arr.length < 6 && !arr.includes(s)) { arr.push(s); snippetsById.set(id, arr); }
};
const addHint = (id, h) => {
  if (!h) return;
  const arr = hintsById.get(id) || [];
  if (arr.length < 4 && !arr.includes(h)) { arr.push(h); hintsById.set(id, arr); }
};

const extractSchema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    matched: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          id: { type: 'string', description: 'id of an already-known entity from the provided index' },
          anchor: { type: 'string' },
          aliases: {
            type: 'array',
            items: { type: 'string' },
            description: 'Any NEW name-forms seen here (titles, full names, epithets, in-world identifiers). [] if none.',
          },
        },
        required: ['id', 'anchor', 'aliases'],
      },
    },
    new: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          name: { type: 'string' },
          aliases: { type: 'array', items: { type: 'string' } },
          type: { type: 'string', enum: ['person', 'creature', 'faction', 'ai_system', 'place', 'other'] },
          tag: { type: 'string', enum: ['in_world', 'real_world_ref', 'media_ref', 'item_object'] },
          roleHint: { type: 'string' },
          mentions: {
            type: 'array',
            items: {
              type: 'object',
              additionalProperties: false,
              properties: { anchor: { type: 'string' }, snippet: { type: 'string' } },
              required: ['anchor', 'snippet'],
            },
          },
        },
        required: ['name', 'aliases', 'type', 'tag', 'roleHint', 'mentions'],
      },
    },
  },
  required: ['matched', 'new'],
};

const describeSchema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    descriptions: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          id: { type: 'string' },
          description: { type: 'string' },
          significance: { type: 'string', enum: ['major', 'supporting', 'minor', 'mentioned'] },
        },
        required: ['id', 'description', 'significance'],
      },
    },
  },
  required: ['descriptions'],
};

const seriesRules = seriesNotes.length
  ? `\nSERIES-SPECIFIC RULES:\n${seriesNotes.map((n) => `- ${n}`).join('\n')}\n`
  : '';

// Prompt layout matters for prompt caching: everything that is identical for every chapter of
// this book (instructions, series rules, the frozen prior-books index) comes FIRST; the parts
// that change per chapter (this book's new entities, the file path) come LAST.
const extractPrompt = (path) =>
  `You are extracting named entities from ONE chapter of "${seriesTitle}" by ${seriesAuthor} (Book ${bookNumber}), processed in reading order.

Each line of the chapter file is annotated like [B${bookNumber}·C3·¶5]; the token inside the brackets is the EXACT citation for that paragraph. Return anchors WITHOUT the square brackets (e.g. B${bookNumber}·C3·¶5).

For EVERY paragraph in which a qualifying entity appears:
- If it refers to an already-known entity above — by name, alias, title, epithet, or context (an epithet, role, or description the text clearly ties to a known entity) — add an entry to "matched" with that entity's exact id, the exact anchor, and an "aliases" array of any NEW name-forms for it that appear here (otherwise []).
- Otherwise add it to "new": name (clearest form), aliases used here, type (person|creature|faction|ai_system|place|other), tag, a short factual roleHint, and mentions [{anchor, snippet}].

ALIASES:
- Capture every distinct NAME-FORM as an alias: full names, name+title ("Lady Vane", "Mr Asano"), nicknames ("Hump"), epithets used as a name, and in-world identifiers. Put them in the "aliases" of a matched entry if the entity is known, or of a new entry if first seen.
- Aliases are NAMES. NEVER record descriptive phrases ("the man behind the desk", "the winded woman", "the big one"), kinship or relationship references ("my son", "her daughter", "his familiar", "your friend"), or generic role nouns ("the mayor", "the landlady", "the director") as aliases. Such phrases are how you RECOGNISE a mention — they are not name-forms to store.

EXHAUSTIVE APPEARANCE LOGGING:
- Log EVERY paragraph (¶) where an entity appears — one matched entry per (entity, paragraph). If an entity appears in 14 paragraphs, emit 14 matched entries. Same for new entities: list every paragraph mention.

WHAT COUNTS AS AN ENTITY:
- Include only NAMED proper nouns or a specifically individuated entity: named people, named creatures/pets, named antagonists, named factions/orgs/companies, distinct AI/system voices, named places, named items.
- DO NOT include generic species, roles, groups, or common-noun categories ("goblin", "soldier", "human", "the guards", "the city"). Only the SPECIFIC named instance counts.
- When unsure whether something is a named individual vs a generic category, EXCLUDE it.

MATCHING NORMALIZATION:
- Treat title/role prefixes as the same entity: "Captain Frank Q" = "Frank Q". Match case-insensitively and ignore punctuation.
${seriesRules}
tag meanings:
- in_world: a real entity inside the story world
- real_world_ref: an actual real-world person/company/place referenced (Amazon, Charles Bronson)
- media_ref: a pop-culture / fictional-media reference (Baby Yoda, Call of Duty)
- item_object: a named item, weapon, achievement, in-world show/program, or product

Rules:
- Only use anchors that literally appear in the file; copy them verbatim.
- If an entity is already in the known list, it goes in "matched" (with its id), never in "new".
- One row per entity within "new" (collect ALL its paragraph mentions into that row's mentions array).

ALREADY-KNOWN entities from earlier books (JSON: id, canonicalName, aliases, type):
${frozenIndexJson}

ALSO ALREADY-KNOWN — discovered earlier in THIS book (match against these too; never re-create them):
${JSON.stringify(addedThisBook)}

ALIASES LEARNED THIS BOOK for the already-known entities above (id → additional name-forms; match these too):
${JSON.stringify(Object.fromEntries([...learnedAliases].map(([id, set]) => [id, [...set]])))}

Use the Read tool to read this chapter file: ${path}`;

const describePrompt = (batch) =>
  `You are writing reference descriptions of newly-introduced characters/entities in "${seriesTitle}" by ${seriesAuthor}.

For each entity below, write a 2-4 sentence "description" and assign a "significance" (major | supporting | minor | mentioned). Full-series spoilers are allowed; use well-established canon, but ground specific claims in the provided role hints / snippets and do not invent. Return one entry per input id.

Entities (JSON):
${JSON.stringify(batch)}`;

// ---- Phase 1: Extract (sequential, in reading order) ----
phase('Extract');
let dropped = 0;
for (let i = 0; i < sectionFiles.length; i++) {
  const path = `${sectionDir}/${sectionFiles[i]}`;
  const label = sectionFiles[i].replace(/\.txt$/, '');
  const res = await agentRetry(extractPrompt(path), {
    ...agentOpts,
    schema: extractSchema,
    phase: 'Extract',
    label: `${seriesId}:extract:${label}`,
  });
  if (!res) continue;

  for (const m of (res.matched || [])) {
    if (!ids.has(m.id)) { dropped++; continue; }
    matched.push({ id: m.id, anchor: m.anchor, aliases: m.aliases || [] });
    // Feed newly learned name-forms back into what later chapters see, so a character first
    // known as "the branch director" is recognised by name once the text supplies it.
    for (const alias of (m.aliases || [])) {
      const added = addedById.get(m.id);
      if (added) { if (!added.aliases.includes(alias)) added.aliases.push(alias); }
      else { let set = learnedAliases.get(m.id); if (!set) { set = new Set(); learnedAliases.set(m.id, set); } set.add(alias); }
    }
  }
  for (const f of (res.new || [])) {
    const id = makeId(f.name, ids);
    ids.add(id);
    const anchors = [...new Set((f.mentions || []).map((x) => x.anchor))];
    const first = (f.mentions || [])[0] || null;
    const ent = {
      id,
      canonicalName: f.name,
      aliases: [...new Set(f.aliases || [])],
      type: f.type,
      tags: [f.tag],
      significance: 'minor',
      description: '',
      firstAppearance: first ? { anchor: first.anchor, snippet: first.snippet } : null,
      appearances: anchors,
    };
    newById.set(id, ent);
    const entry = { id, canonicalName: ent.canonicalName, aliases: [...ent.aliases], type: ent.type };
    addedThisBook.push(entry);
    addedById.set(id, entry);
    for (const mn of (f.mentions || [])) addSnippet(id, mn.snippet);
    addHint(id, f.roleHint);
  }
  if ((i + 1) % 10 === 0 || i === sectionFiles.length - 1) {
    log(`Processed ${i + 1}/${sectionFiles.length} sections — ${newById.size} new entities, ${matched.length} matched mentions`);
  }
}
if (dropped > 0) log(`Note: dropped ${dropped} matched mentions with unknown ids`);

// ---- Phase 2: Describe (new entities only; parallel batches) ----
phase('Describe');
const toDescribe = [...newById.values()];
const BATCH = 10;
const batches = [];
for (let i = 0; i < toDescribe.length; i += BATCH) {
  batches.push(toDescribe.slice(i, i + BATCH).map((e) => ({
    id: e.id,
    canonicalName: e.canonicalName,
    type: e.type,
    aliases: e.aliases,
    roleHints: hintsById.get(e.id) || [],
    snippets: snippetsById.get(e.id) || [],
  })));
}
const describeResults = await parallel(batches.map((batch, bi) => () =>
  agentRetry(describePrompt(batch), { ...agentOpts, schema: describeSchema, phase: 'Describe', label: `${seriesId}:describe:batch-${bi + 1}` }),
));
const descById = new Map();
for (const r of describeResults) {
  if (!r || !Array.isArray(r.descriptions)) continue;
  for (const d of r.descriptions) descById.set(d.id, d);
}
for (const ent of newById.values()) {
  const d = descById.get(ent.id);
  if (d) { ent.description = d.description; ent.significance = d.significance; }
}

log(`Done: ${newById.size} new entities, ${matched.length} matched mentions for book ${bookNumber}`);

// Arrays crossing the workflow VM boundary are capped at 4096 items, and a long book easily
// logs more matched mentions than that. Return both lists in chunks; the caller flattens them
// (matched = matchedChunks.flat(), newEntities = newEntityChunks.flat()) when saving the delta.
const CHUNK = 4000;
const chunk = (arr) => {
  const out = [];
  for (let i = 0; i < arr.length; i += CHUNK) out.push(arr.slice(i, i + CHUNK));
  return out;
};
return {
  booksProcessed: [...startBooksProcessed, bookNumber],
  matchedChunks: chunk(matched),
  newEntityChunks: chunk([...newById.values()]),
};
